import { Page, Locator } from '@playwright/test';

export class MyAccountPage {
    private readonly page: Page;

    // Locators
    private readonly headingMyAccount: Locator;
    private readonly lnkLogout: Locator;

    constructor(page: Page) {
        this.page = page;

        // Initialize locators with CSS selectors
        this.headingMyAccount = page.locator('#content').getByRole('heading', { name: 'My Account', exact: true });
        this.lnkLogout = page.locator('#column-right').getByRole('link', { name: 'Logout' });
    }

    /**
     * Verifies the My Account page (authenticated dashboard) is displayed
     * @returns Promise<boolean> - true if the My Account page is displayed
     */
    async isMyAccountPageExists(): Promise<boolean> {
        try {
            await this.page.waitForURL(/route=account\/account/, { waitUntil: 'domcontentloaded' });
            await this.headingMyAccount.waitFor({ state: 'visible' });
            return true;
        } catch (error) {
            console.log(`Error checking My Account page: ${error}`);
            return false;
        }
    }

    /**
     * Verifies the authenticated "Logout" account navigation option is available
     * @returns Promise<boolean> - true if the Logout link is displayed
     */
    async isLogoutLinkExists(): Promise<boolean> {
        try {
            await this.lnkLogout.waitFor({ state: 'visible' });
            return true;
        } catch (error) {
            console.log(`Error checking Logout link: ${error}`);
            return false;
        }
    }

    /**
     * Clicks "Logout" in the account navigation
     */
    async clickLogout(): Promise<void> {
        await this.lnkLogout.click();
    }
}
